<?php
declare(strict_types=1);require_once __DIR__.'/../../app/bootstrap.php';require_once __DIR__.'/../../app/Modules/QRExperience/helpers.php';$s=qrx_all_settings('draft')?:qrx_all_settings('published');$layout=qrx_layout('draft');$campaigns=qrx_campaigns(true);$enabled=[];foreach($layout as $row)if($row['enabled'])$enabled[]=$row['id'];
function qrx_preview_section(string $id,array $s,array $campaigns): void {if($id==='hero'){?><section class="hero <?=e($s['hero_variant']??'fullscreen')?>"><small>QR EXPERIENCE</small><h1><?=e($s['brand_name']??'CherryHouse')?></h1><p><?=e($s['tagline']??'Lezzetin dijital deneyimi')?></p></section><?php }elseif($id==='announcement'&&$campaigns){$c=$campaigns[0];?><section class="campaign" style="--cb:<?=e($c['background_color'])?>;--ct:<?=e($c['text_color'])?>"><?php if(($c['media_type']??'none')==='image'&&!empty($c['media_url'])):?><img src="<?=e($c['media_url'])?>" alt=""><?php elseif(($c['media_type']??'none')==='video'&&!empty($c['media_url'])):?><video src="<?=e($c['media_url'])?>" muted autoplay loop playsinline></video><?php endif;?><div><b><?=e($c['title'])?></b><p><?=e($c['subtitle']??'')?></p><?php if(!empty($c['button_text'])):?><a href="<?=e($c['button_url']?:'#')?>"><?=e($c['button_text'])?></a><?php endif;?></div></section><?php }elseif($id==='categories'){?><div class="chips"><b>Tümü</b><b>Kahveler</b><b>Ana Yemekler</b><b>Tatlılar</b></div><?php }elseif($id==='featured'){?><main class="wrap"><h2>Öne Çıkanlar</h2><article class="card"><div class="photo"></div><div class="content"><div class="row"><div><span class="tag">Şef Önerisi</span><h3>Signature Burger</h3></div><span class="price">₺325</span></div><p>Özel sos, seçkin malzemeler ve dengeli lezzet.</p></div></article></main><?php }elseif($id==='menu'){?><section class="wrap"><h2>Menü</h2><article class="card compact"><div class="content"><div class="row"><h3>Cold Brew</h3><span class="price">₺140</span></div><p>18 saat demlenmiş, yumuşak içimli kahve.</p></div></article></section><?php }elseif($id==='chef'){?><section class="strip"><h2>Şefin Seçimi</h2><p>Mevsimin en iyi malzemeleriyle hazırlanan özel tabaklar.</p></section><?php }elseif($id==='story'){?><section class="wrap story"><h2>Hikâyemiz</h2><p>CherryHouse deneyimini her masada aynı kaliteyle sunuyoruz.</p></section><?php }elseif($id==='social'){?><section class="social">Bizi sosyal medyada takip et · @cherryhouse</section><?php }elseif($id==='footer'){?><footer>CherryHouse · Afiyet olsun</footer><?php }}
?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>:root{--p:<?=e($s['primary_color']??'#d71920')?>;--s:<?=e($s['secondary_color']??'#111827')?>;--bg:<?=e($s['background_color']??'#f8fafc')?>;--t:<?=e($s['text_color']??'#111827')?>;--r:<?=intval($s['radius']??18)?>px}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--t);font-family:<?=e($s['font_family']??'Inter')?>,Arial,sans-serif}.hero{min-height:280px;padding:30px 22px;display:flex;flex-direction:column;justify-content:flex-end;color:white;background:linear-gradient(145deg,var(--s),var(--p))}.hero.split{min-height:220px}.hero.minimal{min-height:180px}.hero small{opacity:.75;letter-spacing:.18em}.hero h1{font-size:40px;margin:8px 0}.campaign{margin:16px 18px;border-radius:var(--r);overflow:hidden;background:var(--cb);color:var(--ct);display:grid;grid-template-columns:minmax(0,1fr);box-shadow:0 14px 30px #0002}.campaign img,.campaign video{width:100%;max-height:190px;object-fit:cover}.campaign>div{padding:18px}.campaign b{font-size:22px}.campaign p{margin:8px 0}.campaign a{display:inline-block;background:#fff;color:#111;padding:9px 13px;border-radius:999px;text-decoration:none}.chips{display:flex;gap:8px;overflow:auto;padding:18px}.chips b{white-space:nowrap;background:#fff;padding:10px 14px;border-radius:999px}.wrap{padding:0 18px 24px}.card{background:#fff;border-radius:var(--r);overflow:hidden;margin-bottom:16px;box-shadow:0 10px 25px #00000010}.photo{height:150px;background:linear-gradient(135deg,#ddd,#aaa)}.content{padding:16px}.row{display:flex;justify-content:space-between;gap:12px}.price{color:var(--p);font-weight:800}.tag{font-size:11px;background:#fee2e2;color:var(--p);padding:5px 8px;border-radius:999px}.strip,.social,footer{padding:26px 18px;text-align:center}.strip{background:var(--s);color:white}.story{padding-top:24px}.social{background:#fff}footer{background:#111827;color:#fff}</style></head><body><?php foreach($layout as $row)if($row['enabled'])qrx_preview_section($row['id'],$s,$campaigns);?></body></html>
